/* ============================================================
   76° — Seventy Six Degrees · tokens.css
   The ONLY file in the system permitted to contain color literals.
   (Slop Firewall A1: any hex/rgb/hsl outside this file is a defect.)
   ============================================================ */

@layer sv-tokens {
  :root {
    /* neutrals — the wall & the ink */
    --sv-band:       #1B1F26;   /* ink band (header) */
    --sv-band-line:  #2C323B;   /* hairlines on band */
    --sv-band-soft:  #8A93A2;   /* soft text on band */
    --sv-wall:       #F2F3F5;   /* platinum background */
    --sv-paper:      #FFFFFF;   /* card surface */
    --sv-ink:        #1C2026;   /* primary text */
    --sv-ink-soft:   #667080;   /* secondary text */
    --sv-ink-faint:  #99A1AD;   /* labels, hints — never sole carrier (C2) */
    --sv-line:       #E9EBEE;   /* internal hairlines */
    --sv-field-line: #D8DCE1;   /* form field borders */
    --sv-compare:    #D6DAE0;   /* comparison series in charts — the only
                                   permitted non-token chart color, aliased */

    /* seed — Layer 3, per product (default: Cobalt / ERP) */
    --sv-seed:       #2C5BE0;
    --sv-seed-text:  #2C5BE0;   /* seed used AS text; differs when fills pass
                                   but text fails the C1 rule (see Signal) */
    --sv-seed-deep:  #1E44B4;   /* pressed */
    --sv-seed-tint:  #EEF3FE;   /* icon tiles, selected rows */

    /* functional — words and 6px dots ONLY (contrast-verified on paper) */
    --sv-ok:         #14804A;   /* 4.98:1 on white — AA */
    --sv-bad:        #C43D2E;   /* 5.18:1 on white — AA */

    /* scrim — Dialog only, flat, no blur */
    --sv-scrim:      rgba(27, 31, 38, 0.4);

    /* geometry & elevation */
    --sv-r:          4px;                              /* the only radius */
    --sv-shadow:     0 1px 2px rgba(16, 20, 28, 0.05); /* the only shadow */

    /* spacing scale (4px base) */
    --sv-s1: 4px;  --sv-s2: 8px;  --sv-s3: 12px; --sv-s4: 16px;
    --sv-s5: 20px; --sv-s6: 24px; --sv-s7: 32px; --sv-s8: 40px;

    /* type */
    --sv-font-ui:   'Hanken Grotesk Variable', 'Hanken Grotesk', system-ui, sans-serif;
    --sv-font-mono: 'Fragment Mono', ui-monospace, monospace;

    /* motion — opacity/color fades only, never layout (A1).
       Both collapse to 0ms under prefers-reduced-motion. */
    --sv-t-fast: 120ms;
    --sv-t:      160ms;

    /* layering — the only z-index ladder (Firewall E). Non-visual.
       Native <dialog> and [popover] use the browser top layer and
       need no z-index at all — prefer them. */
    --sv-z-band:   10;   /* sticky band / topbar */
    --sv-z-sticky: 20;   /* sticky in-page (table headers) */
    --sv-z-scrim:  30;   /* dialog scrim (non-native fallback) */
    --sv-z-dialog: 40;   /* dialog (non-native fallback) */
    --sv-z-toast:  50;   /* toasts */
    --sv-z-tip:    60;   /* tooltips (non-popover fallback) */
    --sv-z-skip:   70;   /* skip link (C4) — first tab stop, wins over all */
  }

  @media (prefers-reduced-motion: reduce) {
    :root {
      --sv-t-fast: 0ms;
      --sv-t:      0ms;
    }
  }

  /* ---- Per-product seed registry (Layer 3) ------------------
     One seed per product. tint = seed at ~8% on white,
     deep = seed darkened ~20%. New seeds must pass C1:
     seed-on-white >= 4.5:1 AND white-on-seed >= 4.5:1. */

  [data-seed='cobalt'] {
    --sv-seed:      #2C5BE0;   /* ERP · 5.70:1 both ways */
    --sv-seed-text: #2C5BE0;
    --sv-seed-deep: #1E44B4;
    --sv-seed-tint: #EEF3FE;
  }

  [data-seed='verdigris'] {
    --sv-seed:      #12836F;   /* CRM · 5.0:1 both ways */
    --sv-seed-text: #12836F;
    --sv-seed-deep: #0D6152;
    --sv-seed-tint: #EAF5F2;
  }

  [data-seed='signal'] {
    --sv-seed:      #D9531E;   /* POS · fills only (white on seed 4.6:1) */
    --sv-seed-text: #C24413;   /* seed-as-text variant — passes on white */
    --sv-seed-deep: #A83E12;
    --sv-seed-tint: #FCF0EA;
  }
}

/* ============================================================
   76° · base.css — reset, typography defaults, focus contract
   ============================================================ */

@layer sv-base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    margin: 0;
    background: var(--sv-wall);
    color: var(--sv-ink);
    font-family: var(--sv-font-ui);
    font-size: 13px;
    line-height: 1.5;
    font-weight: 500;
    -webkit-font-smoothing: antialiased;
  }

  h1, h2, h3, h4, p, figure, blockquote, dl, dd {
    margin: 0;
  }

  img, svg {
    display: block;
    max-width: 100%;
  }

  button, input, select, textarea {
    font: inherit;
    color: inherit;
  }

  /* C3 · Focus — every interactive element, no exceptions */
  :focus-visible {
    outline: 2px solid var(--sv-seed);
    outline-offset: 2px;
  }

  /* On the band, focus is white for contrast */
  .sv-band :focus-visible {
    outline-color: var(--sv-paper);
  }

  /* A4 · numbers that can change are tabular, always */
  .sv-num {
    font-variant-numeric: tabular-nums;
  }

  /* Mono metadata voice (Law 4) */
  .sv-mono {
    font-family: var(--sv-font-mono);
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.13em;
    text-transform: uppercase;
  }

  /* C4 · Skip link — first tab stop, visible on focus over the band */
  .sv-skip {
    position: absolute;
    left: var(--sv-s4);
    top: var(--sv-s2);
    z-index: var(--sv-z-skip);
    padding: var(--sv-s2) var(--sv-s4);
    background: var(--sv-paper);
    color: var(--sv-ink);
    border-radius: var(--sv-r);
    box-shadow: var(--sv-shadow);
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;
    transform: translateY(-200%);
  }

  .sv-skip:focus-visible {
    transform: none;
  }

  /* Visually hidden, screen-reader available */
  .sv-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* C7 · reduced motion — handled at the token layer: every transition
     in the system uses var(--sv-t) / var(--sv-t-fast), which collapse
     to 0ms under prefers-reduced-motion (see tokens.css). 76° loses
     nothing, by design. */
}

/** Minimal class combiner. No dependency needed. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ');
}
